#[derive(Debug, Clone, PartialEq)]
enum AgeError {
    Empty,
    NotANumber(String),
    TooOld(u32),
}

fn parse_age(text: &str) -> Result<u32, AgeError> {
    let text = text.trim();
    if text.is_empty() {
        return Err(AgeError::Empty);
    }
    let age = match text.parse::<u32>() {
        Ok(n) => n,
        Err(_) => return Err(AgeError::NotANumber(text.to_string())),
    };
    if age > 150 {
        return Err(AgeError::TooOld(age));
    }
    Ok(age)
}

fn main() {
    for text in ["42", " ", "forty", "200"] {
        match parse_age(text) {
            Ok(age) => println!("age {age}"),
            Err(AgeError::Empty) => println!("please type an age"),
            Err(AgeError::NotANumber(t)) => println!("'{t}' is not a number"),
            Err(AgeError::TooOld(n)) => println!("{n} is too old"),
        }
    }
    println!("{}", parse_age("") == Err(AgeError::Empty));
}

