pub enum GuessError {
    TooLow(i32),
    TooHigh(i32),
}

pub struct Guess {
    value: i32,
}

impl Guess {
    pub fn new(value: i32) -> Result<Guess, GuessError> {
        if value < 1 {
            return Err(GuessError::TooLow(value));
        }
        if value > 100 {
            return Err(GuessError::TooHigh(value));
        }
        Ok(Guess { value })
    }

    pub fn value(&self) -> i32 {
        self.value
    }
}

