use std::cmp::Ordering;

use guessing_game::Guess;

fn hint(guess: &Guess, secret: i32) {
    match guess.value().cmp(&secret) {
        Ordering::Less => println!("{} is too small", guess.value()),
        Ordering::Greater => println!("{} is too big", guess.value()),
        Ordering::Equal => println!("{} is right!", guess.value()),
    }
}

fn main() {
    let secret = 64;
    for n in [30, 80, 64] {
        hint(&Guess::new(n), secret);
    }
}

