use std::collections::{HashMap, HashSet};

use crate::{
    book::{Book, Status},
    error::LibraryError,
    fees::{PREMIUM_LOAN_DAYS, due_day},
    member::Member,
    text::{sort_key, title_matches},
};

pub struct Library {
    books: Vec<Book>,
    members: HashMap<u32, Member>,
    next_book_id: u32,
}

impl Library {
    pub fn new() -> Library {
        Library {
            books: Vec::new(),
            members: HashMap::new(),
            next_book_id: 1,
        }
    }

    fn index_of(&self, id: u32) -> Option<usize> {
        for (i, book) in self.books.iter().enumerate() {
            if book.id == id {
                return Some(i);
            }
        }
        None
    }

    pub fn add_book(&mut self, title: &str, author: &str, year: u16) -> u32 {
        let id = self.next_book_id;
        self.next_book_id += 1;
        self.books.push(Book::new(id, title, author, year));
        id
    }

    pub fn add_member(&mut self, id: u32, name: &str, premium: bool) -> Result<(), LibraryError> {
        if self.members.contains_key(&id) {
            return Err(LibraryError::DuplicateMember(id));
        }
        self.members.insert(id, Member::new(id, name, premium));
        Ok(())
    }

    pub fn book(&self, id: u32) -> Option<&Book> {
        for book in &self.books {
            if book.id == id {
                return Some(book);
            }
        }
        None
    }

    pub fn member(&self, id: u32) -> Option<&Member> {
        self.members.get(&id)
    }

    pub fn books_by(&self, author: &str) -> Vec<&Book> {
        let wanted = author.trim().to_lowercase();
        let mut keys = Vec::new();
        for (i, book) in self.books.iter().enumerate() {
            if book.author.trim().to_lowercase() == wanted {
                keys.push((sort_key(&book.title), book.id, i));
            }
        }
        keys.sort();
        let mut out = Vec::new();
        for (_, _, i) in keys {
            out.push(&self.books[i]);
        }
        out
    }

    pub fn search_titles(&self, query: &str) -> Vec<u32> {
        let mut ids = Vec::new();
        for book in &self.books {
            if title_matches(&book.title, query) {
                ids.push(book.id);
            }
        }
        ids
    }

    pub fn count_by_status(&self) -> (usize, usize, usize) {
        let mut available = 0;
        let mut borrowed = 0;
        let mut lost = 0;
        for book in &self.books {
            match book.status {
                Status::Available => available += 1,
                Status::Borrowed {
                    member_id: _,
                    due_day: _,
                } => borrowed += 1,
                Status::Lost => lost += 1,
            }
        }
        (available, borrowed, lost)
    }

    pub fn authors(&self) -> Vec<String> {
        let mut seen = HashSet::new();
        let mut out = Vec::new();
        for book in &self.books {
            if seen.insert(book.author.as_str()) {
                out.push(book.author.clone());
            }
        }
        out.sort();
        out
    }

    pub fn checkout(
        &mut self,
        book_id: u32,
        member_id: u32,
        today: u32,
    ) -> Result<u32, LibraryError> {
        let i = self
            .index_of(book_id)
            .ok_or(LibraryError::NoSuchBook(book_id))?;
        let member = self
            .members
            .get_mut(&member_id)
            .ok_or(LibraryError::NoSuchMember(member_id))?;
        if !self.books[i].is_available() {
            return Err(LibraryError::NotAvailable(book_id));
        }
        if !member.can_borrow() {
            return Err(LibraryError::LimitReached(member_id));
        }
        if today > u32::MAX - PREMIUM_LOAN_DAYS {
            return Err(LibraryError::BadCommand(format!(
                "checkout {book_id} {member_id} {today}"
            )));
        }
        if !self.books[i].checkout(member, today) {
            return Err(LibraryError::NotAvailable(book_id));
        }
        Ok(due_day(today, member.premium))
    }

    pub fn return_book(&mut self, book_id: u32, today: u32) -> Result<u32, LibraryError> {
        let i = self
            .index_of(book_id)
            .ok_or(LibraryError::NoSuchBook(book_id))?;
        let member_id = self.books[i]
            .borrower()
            .ok_or(LibraryError::NotBorrowed(book_id))?;
        let member = self
            .members
            .get_mut(&member_id)
            .ok_or(LibraryError::NoSuchMember(member_id))?;
        self.books[i]
            .return_to_shelf(member, today)
            .ok_or(LibraryError::NotBorrowed(book_id))
    }
}

use crate::{
    error::LibraryError,
    fees::{PREMIUM_LOAN_DAYS, format_cents},
    library::Library,
};

#[derive(Debug, Clone, PartialEq)]
pub enum Command {
    Add {
        title: String,
        author: String,
        year: u16,
    },
    Checkout {
        book_id: u32,
        member_id: u32,
        today: u32,
    },
    Return {
        book_id: u32,
        today: u32,
    },
    Find(String),
    Report,
}

fn bad(line: &str) -> LibraryError {
    LibraryError::BadCommand(line.to_string())
}

fn number(word: Option<&str>, line: &str) -> Result<u32, LibraryError> {
    let word = word.ok_or(bad(line))?;
    word.parse::<u32>().ok().ok_or(bad(line))
}

fn parse_add(rest: &str, line: &str) -> Result<Command, LibraryError> {
    let mut fields = rest.split('|');
    let title = fields.next().ok_or(bad(line))?.trim();
    let author = fields.next().ok_or(bad(line))?.trim();
    let year = fields.next().ok_or(bad(line))?.trim();
    if fields.next().is_some() {
        return Err(bad(line));
    }
    let year = year.parse::<u16>().ok().ok_or(bad(line))?;
    Ok(Command::Add {
        title: title.to_string(),
        author: author.to_string(),
        year,
    })
}

pub fn parse_command(line: &str) -> Result<Command, LibraryError> {
    let text = line.trim();
    if text.contains('\n') || text.contains('\r') {
        return Err(bad(line));
    }
    let mut words = text.split_whitespace();
    let keyword = words.next().ok_or(bad(line))?;
    let rest = text[keyword.len()..].trim_start();
    match keyword {
        "add" => parse_add(rest, line),
        "checkout" => {
            let book_id = number(words.next(), line)?;
            let member_id = number(words.next(), line)?;
            let today = number(words.next(), line)?;
            if words.next().is_some() || today > u32::MAX - PREMIUM_LOAN_DAYS {
                return Err(bad(line));
            }
            Ok(Command::Checkout {
                book_id,
                member_id,
                today,
            })
        }
        "return" => {
            let book_id = number(words.next(), line)?;
            let today = number(words.next(), line)?;
            if words.next().is_some() {
                return Err(bad(line));
            }
            Ok(Command::Return { book_id, today })
        }
        "find" => {
            if rest.is_empty() {
                return Err(bad(line));
            }
            Ok(Command::Find(rest.to_string()))
        }
        "report" => {
            if words.next().is_some() {
                return Err(bad(line));
            }
            Ok(Command::Report)
        }
        _ => Err(bad(line)),
    }
}

impl Library {
    pub fn execute(&mut self, cmd: Command) -> Result<String, LibraryError> {
        match cmd {
            Command::Add {
                title,
                author,
                year,
            } => {
                let id = self.add_book(&title, &author, year);
                Ok(format!("Added book {id}."))
            }
            Command::Checkout {
                book_id,
                member_id,
                today,
            } => {
                let due = self.checkout(book_id, member_id, today)?;
                Ok(format!("Book {book_id} due on day {due}."))
            }
            Command::Return { book_id, today } => {
                let fee = self.return_book(book_id, today)?;
                Ok(format!("Fee: {}.", format_cents(fee)))
            }
            Command::Find(query) => {
                let ids = self.search_titles(&query);
                if ids.is_empty() {
                    return Ok(String::from("Found: none."));
                }
                let mut out = String::from("Found: ");
                for (i, id) in ids.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    out.push_str(&id.to_string());
                }
                out.push('.');
                Ok(out)
            }
            Command::Report => {
                let (available, borrowed, lost) = self.count_by_status();
                Ok(format!(
                    "Available: {available}\nBorrowed: {borrowed}\nLost: {lost}"
                ))
            }
        }
    }
}

